class ThreadChannel:
    """Async RPC channel over thread-safe queues.

    For use in the main thread with an asyncio event loop. Thread-safe.
    """

    def __init__(
        self,
        send_queue: queue.Queue,
        recv_queue: queue.Queue,
        executor: ThreadPoolExecutor | None = None,
    ):
        """Create a channel from thread-safe queues.

        Args:
            send_queue: Queue for outgoing messages (to worker)
            recv_queue: Queue for incoming messages (from worker)
            executor: Thread pool for async operations (created if None)
        """
        self._send_queue = send_queue
        self._recv_queue = recv_queue
        self._executor = executor or ThreadPoolExecutor(max_workers=2)
        self._owns_executor = executor is None
        self._closed = threading.Event()

    async def send(self, key: str, data: Any) -> None:
        """Send a message."""
        if self._closed.is_set():
            raise ChannelClosed("Channel is closed")

        loop = asyncio.get_running_loop()
        try:
            await loop.run_in_executor(
                self._executor,
                self._send_queue.put,
                (key, data),
            )
        except Exception as e:
            self._closed.set()
            raise ChannelBroken(f"Channel broken: {e}")

    async def recv(self, timeout: float | None = None) -> tuple[str, Any]:
        """Receive a message with optional timeout."""
        if self._closed.is_set():
            raise ChannelClosed("Channel is closed")

        loop = asyncio.get_running_loop()

        def blocking_recv():
            if timeout is None:
                # No caller timeout — loop with sentinel checks so the
                # thread can exit when the channel closes or Python shuts down.
                while not self._closed.is_set() and not _module_shutdown.is_set():
                    try:
                        return self._recv_queue.get(timeout=_RECV_SENTINEL_TIMEOUT)
                    except queue.Empty:
                        continue
                raise ChannelClosed("Channel is closed")
            else:
                deadline = time.monotonic() + timeout
                while not self._closed.is_set() and not _module_shutdown.is_set():
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        raise RecvTimeout(f"Receive timed out after {timeout}s")
                    try:
                        return self._recv_queue.get(
                            timeout=min(_RECV_SENTINEL_TIMEOUT, remaining),
                        )
                    except queue.Empty:
                        continue
                raise ChannelClosed("Channel is closed")

        try:
            result = await loop.run_in_executor(self._executor, blocking_recv)
        except (RecvTimeout, ChannelClosed):
            raise
        except Exception as e:
            self._closed.set()
            raise ChannelBroken(f"Channel broken: {e}")

        if result[0] == RPC_KEY_SHUTDOWN:
            self._closed.set()
            raise ChannelClosed("Channel was shut down")

        return result

    async def try_recv(self) -> tuple[str, Any] | None:
        """Non-blocking receive."""
        if self._closed.is_set():
            raise ChannelClosed("Channel is closed")

        try:
            result = self._recv_queue.get_nowait()
        except queue.Empty:
            return None
        except Exception as e:
            self._closed.set()
            raise ChannelBroken(f"Channel broken: {e}")

        if result[0] == RPC_KEY_SHUTDOWN:
            self._closed.set()
            raise ChannelClosed("Channel was shut down")

        return result

    async def close(self) -> None:
        """Close the channel."""
        if not self._closed.is_set():
            self._closed.set()
            # Send shutdown to worker
            try:
                self._send_queue.put_nowait((RPC_KEY_SHUTDOWN, None))
            except Exception:
                pass
            # Also put shutdown on recv queue to unblock any recv() calls
            try:
                self._recv_queue.put_nowait((RPC_KEY_SHUTDOWN, None))
            except Exception:
                pass

            if self._owns_executor:
                self._executor.shutdown(wait=False)

    @property
    def is_closed(self) -> bool:
        return self._closed.is_set()

